    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Extend a repeated non-background color diagonally outward from its
    # endpoint when a diagonal continuation leads to the grid edge.
    for color in set(v for row in grid for v in row if v != bg):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(pts) < 3:
