            for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                # This point must be an endpoint: there are same-color pixels
                # behind it, but not in the outward direction.
                if (r-dr, c-dc) in pts and (r-2*dr, c-2*dc) in pts:
                    rr, cc = r+dr, c+dc
                    while 0 <= rr < h and 0 <= cc < w:
