def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Continue diagonal rays of a color from pixels that are diagonally
    # connected to another pixel of that color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                ar, ac = r - dr, c - dc
                if not (0 <= ar < h and 0 <= ac < w and grid[ar][ac] == color):
                    continue
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
